  const isAlive = (cell: Cell): boolean => living.has(key(cell));
  const liveNeighborCount = (cell: Cell): number =>
    neighbors(cell).filter(isAlive).length;

  const survivors = cells.filter((cell) => {
    const count = liveNeighborCount(cell);
    return count === 2 || count === 3;
  });

  const births = candidatesForBirth(cells).filter(
    (cell) => liveNeighborCount(cell) === 3,
  );

  return [...survivors, ...births];
}

/** Dead cells adjacent to at least one living cell — the only ones that can be born. */
function candidatesForBirth(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(key));
  const seen = new Set<string>();
  const candidates: Cell[] = [];

  for (const cell of cells) {
    for (const neighbor of neighbors(cell)) {
      const id = key(neighbor);
      if (living.has(id) || seen.has(id)) continue;
      seen.add(id);
      candidates.push(neighbor);
    }
  }

  return candidates;
}

